-- This table is included in an airflow definition. Any table or
-- column name change must be reflected there.
CREATE TABLE `ts_logical_alerts` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `repository_id` bigint unsigned NOT NULL,
  `number` int unsigned NOT NULL,
  `rule_id` bigint unsigned NOT NULL,
  `sarif_identifier` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `resolution` int NOT NULL DEFAULT '0',
  `resolution_note` varchar(280) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `resolver_id` int unsigned DEFAULT NULL,
  `resolved_at` datetime(6) DEFAULT NULL,
  `weight` smallint unsigned NOT NULL DEFAULT '0',
  `stable_alert_identifier` binary(21) NOT NULL,
  `severity_level` tinyint unsigned DEFAULT NULL,
  `security_severity` double DEFAULT NULL,
  `soft_deleted_at` datetime(6) DEFAULT NULL,
  `soft_deleter_id` int unsigned DEFAULT NULL,
  `guid` char(36) COLLATE utf8mb4_general_ci NOT NULL,
  `file_path` varchar(4096) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `start_line` int unsigned DEFAULT NULL,
  `end_line` int unsigned DEFAULT NULL,
  `start_column` int unsigned DEFAULT NULL,
  `end_column` int unsigned DEFAULT NULL,
  `message` varchar(4096) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `message_markdown` varchar(4096) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `file_classification` json DEFAULT NULL,
  `default_configuration_id` bigint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `index_logical_alerts_on_repository_id_and_number` (`repository_id`,`number`),
  UNIQUE KEY `index_logical_alerts_uniq_location` (`repository_id`,`stable_alert_identifier`),
  KEY `index_logical_alerts_on_repository_id_deleted` (`repository_id`,`soft_deleted_at`),
  KEY `index_logical_alerts_on_repository_id_updated_at` (`repository_id`, `updated_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
